mapper.select:
SELECT user_id
FROM group_chat_member
WHERE group_id = #{groupId}

mapper.update:
UPDATE group_chat_member
SET last_read_message_id = #{messageId}
WHERE group_id = #{groupId}
  AND user_id = #{userId}
  AND last_read_message_id < #{messageId}

mapper.select:
SELECT COUNT(1)
FROM group_chat_member
WHERE group_id = #{groupId}

mapper.delete:
DELETE
FROM group_chat_member
WHERE group_id = #{groupId}
  AND user_id = #{userId}
